<?php
namespace Tests\Feature;use App\Models\Company;use App\Models\Job;use App\Models\JobApplication;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class AdvancedCvAndMatchingTest extends TestCase{use RefreshDatabase;public function test_candidate_controls_public_cv_link():void{$user=User::factory()->create(['account_type'=>'candidate']);$user->candidateProfile()->create(['professional_title'=>'Desarrollador Laravel','skills'=>['PHP','Laravel']]);$url=$this->actingAs($user,'sanctum')->postJson('/api/v1/candidate/cv/share',['enabled'=>true])->assertOk()->json('data.url');$token=basename($url);$this->getJson('/api/v1/cv/'.$token)->assertOk()->assertJsonPath('data.professional_title','Desarrollador Laravel');$this->actingAs($user,'sanctum')->postJson('/api/v1/candidate/cv/share',['enabled'=>false])->assertOk();$this->getJson('/api/v1/cv/'.$token)->assertNotFound();}public function test_matching_is_explainable_for_candidate_and_company():void{$owner=User::factory()->create(['account_type'=>'company']);$company=Company::create(['name'=>'Acme','slug'=>'acme','status'=>'active']);$company->members()->attach($owner->id,['role'=>'owner','status'=>'active']);$job=Job::create(['company_id'=>$company->id,'slug'=>'backend-laravel','title'=>'Desarrollador Laravel','summary'=>'Servicios PHP','description'=>'Laravel y PostgreSQL','requirements'=>['PHP','Laravel'],'location'=>'Santiago','modality'=>'Remoto','contract_type'=>'Tiempo completo','status'=>'active']);$candidate=User::factory()->create(['account_type'=>'candidate']);$profile=$candidate->candidateProfile()->create(['professional_title'=>'Desarrollador Laravel','skills'=>['PHP','Laravel'],'preferred_modalities'=>['Remoto'],'preferred_provinces'=>['Santiago'],'experience'=>[['role'=>'Developer']]]);$this->actingAs($candidate,'sanctum')->getJson('/api/v1/candidate/jobs/backend-laravel/match')->assertOk()->assertJsonPath('data.level','alta')->assertJsonStructure(['data'=>['score','strengths','gaps','disclaimer']]);$application=JobApplication::create(['job_id'=>$job->id,'user_id'=>$candidate->id,'status'=>'submitted','profile_snapshot'=>['profile'=>$profile->toArray()],'applied_at'=>now()]);$this->actingAs($owner,'sanctum')->getJson("/api/v1/company/applications/{$application->id}/match")->assertOk()->assertJsonPath('data.level','alta');}}
